[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <meta name="description" content="SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most." />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet" />
  <style>
    /* ─── Reset & Base ─── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Plus Jakarta Sans', sans-serif;
      background: #fff;
      color: #0a0a0a;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }
    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { cursor: pointer; border: none; background: none; font-family: inherit; }

    /* ─── CSS Variables ─── */
    :root {
      --purple: #7638FA;
      --purple-light: #9B6FFC;
      --purple-dark: #5A28D4;
      --orange: #FF7A00;
      --orange-light: #FF9B40;
      --black: #0a0a0a;
      --gray-100: #f5f5f7;
      --gray-200: #e8e8ed;
      --gray-400: #999;
      --gray-600: #555;
      --white: #fff;
      --radius-sm: 8px;
      --radius-md: 16px;
      --radius-lg: 24px;
      --radius-xl: 32px;
      --shadow-card: 0 2px 16px rgba(0,0,0,0.08), 0 1px 4px rgba(0,0,0,0.04);
      --shadow-hover: 0 8px 40px rgba(118,56,250,0.18), 0 2px 8px rgba(0,0,0,0.08);
    }

    /* ─── Header ─── */
    .header {
      position: fixed;
      top: 0; left: 0; right: 0;
      z-index: 100;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 40px;
      height: 68px;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid rgba(0,0,0,0.06);
      transition: box-shadow 0.3s;
    }
    .header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.08); }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      font-size: 20px;
      letter-spacing: -0.5px;
      color: var(--black);
    }
    .logo-icon {
      width: 36px; height: 36px;
      border-radius: 10px;
      background: linear-gradient(135deg, var(--purple) 0%, var(--orange) 100%);
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
    }
    .logo-icon svg { width: 20px; height: 20px; fill: #fff; }

    .header-right { display: flex; align-items: center; gap: 16px; }

    .btn-login {
      padding: 9px 22px;
      border-radius: 999px;
      border: 1.5px solid var(--black);
      font-size: 14px;
      font-weight: 600;
      color: var(--black);
      transition: all 0.2s;
      white-space: nowrap;
    }
    .btn-login:hover { background: var(--black); color: #fff; }

    /* Hamburger */
    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      width: 28px;
      padding: 4px 0;
    }
    .hamburger span {
      display: block;
      height: 2px;
      background: var(--black);
      border-radius: 2px;
      transition: all 0.3s cubic-bezier(0.4,0,0.2,1);
      transform-origin: center;
    }
    .hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.open span:nth-child(2) { opacity: 0; transform: scaleX(0); }
    .hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    /* Mobile Nav Overlay */
    .mobile-nav {
      display: none;
      position: fixed;
      inset: 0;
      z-index: 99;
      background: rgba(255,255,255,0.98);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 8px;
      opacity: 0;
      transform: translateY(-10px);
      transition: opacity 0.3s, transform 0.3s;
      pointer-events: none;
    }
    .mobile-nav.open {
      display: flex;
      opacity: 1;
      transform: translateY(0);
      pointer-events: all;
    }
    .mobile-nav a {
      font-size: 28px;
      font-weight: 700;
      color: var(--black);
      padding: 12px 40px;
      border-radius: var(--radius-md);
      transition: color 0.2s;
      letter-spacing: -0.5px;
    }
    .mobile-nav a:hover { color: var(--purple); }
    .mobile-nav .mobile-login {
      margin-top: 16px;
      padding: 14px 48px;
      border-radius: 999px;
      background: var(--black);
      color: #fff;
      font-size: 18px;
      font-weight: 700;
    }
    .mobile-nav .mobile-login:hover { background: var(--purple); color: #fff; }

    /* ─── Hero ─── */
    .hero {
      position: relative;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 120px 40px 80px;
      overflow: hidden;
      background: #fff;
    }

    /* Gradient mesh background */
    .hero-bg {
      position: absolute;
      inset: 0;
      overflow: hidden;
      z-index: 0;
    }
    .hero-blob {
      position: absolute;
      border-radius: 50%;
      filter: blur(80px);
      opacity: 0.22;
    }
    .hero-blob-1 {
      width: 700px; height: 700px;
      background: var(--purple);
      top: -150px; right: -100px;
    }
    .hero-blob-2 {
      width: 500px; height: 500px;
      background: var(--orange);
      bottom: -100px; left: -100px;
    }
    .hero-blob-3 {
      width: 400px; height: 400px;
      background: #FF3CA0;
      top: 50%; left: 50%;
      transform: translate(-50%, -50%);
    }

    /* Geometric accent shapes */
    .hero-shape {
      position: absolute;
      border-radius: 50%;
      z-index: 1;
    }
    .hero-shape-1 {
      width: 180px; height: 180px;
      border: 2px solid rgba(118,56,250,0.15);
      top: 18%; right: 12%;
      animation: float1 6s ease-in-out infinite;
    }
    .hero-shape-2 {
      width: 80px; height: 80px;
      background: linear-gradient(135deg, var(--orange) 0%, #FFB347 100%);
      opacity: 0.18;
      bottom: 28%; right: 20%;
      animation: float2 8s ease-in-out infinite;
    }
    .hero-shape-3 {
      width: 40px; height: 40px;
      background: var(--purple);
      opacity: 0.25;
      top: 32%; left: 8%;
      border-radius: var(--radius-sm);
      transform: rotate(20deg);
      animation: float3 7s ease-in-out infinite;
    }

    @keyframes float1 { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-18px)} }
    @keyframes float2 { 0%,100%{transform:translateY(0)} 50%{transform:translateY(14px)} }
    @keyframes float3 { 0%,100%{transform:translateY(0) rotate(20deg)} 50%{transform:translateY(-12px) rotate(35deg)} }

    .hero-content {
      position: relative;
      z-index: 2;
      max-width: 900px;
      text-align: center;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 18px;
      border-radius: 999px;
      background: rgba(118,56,250,0.08);
      border: 1px solid rgba(118,56,250,0.2);
      font-size: 13px;
      font-weight: 600;
      color: var(--purple);
      margin-bottom: 32px;
      letter-spacing: 0.3px;
    }
    .hero-badge-dot {
      width: 6px; height: 6px;
      border-radius: 50%;
      background: var(--purple);
      animation: pulse 2s ease-in-out infinite;
    }
    @keyframes pulse {
      0%,100%{opacity:1; transform:scale(1)}
      50%{opacity:0.5; transform:scale(0.8)}
    }

    .hero-title {
      font-size: clamp(40px, 7vw, 80px);
      font-weight: 800;
      line-height: 1.05;
      letter-spacing: -2.5px;
      color: var(--black);
      margin-bottom: 28px;
    }
    .hero-title .highlight {
      background: linear-gradient(90deg, var(--purple) 0%, #FF3CA0 50%, var(--orange) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero-sub {
      font-size: 18px;
      color: var(--gray-600);
      max-width: 560px;
      margin: 0 auto 40px;
      line-height: 1.65;
      font-weight: 500;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 16px 40px;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--purple) 0%, #5A28D4 100%);
      color: #fff;
      font-size: 17px;
      font-weight: 700;
      letter-spacing: -0.2px;
      transition: all 0.25s;
      box-shadow: 0 8px 32px rgba(118,56,250,0.35);
    }
    .hero-cta:hover {
      transform: translateY(-2px);
      box-shadow: 0 12px 40px rgba(118,56,250,0.45);
    }
    .hero-cta svg { width: 18px; height: 18px; stroke: #fff; stroke-width: 2.5; }

    /* App preview mockup */
    .hero-phones {
      position: relative;
      margin-top: 72px;
      display: flex;
      justify-content: center;
      gap: 24px;
      z-index: 2;
    }
    .phone-mockup {
      width: 200px;
      border-radius: 36px;
      overflow: hidden;
      box-shadow: 0 32px 80px rgba(0,0,0,0.2);
      border: 2px solid rgba(255,255,255,0.8);
      transform-origin: bottom center;
    }
    .phone-mockup:nth-child(1) { transform: rotate(-5deg) translateY(20px); }
    .phone-mockup:nth-child(2) { transform: rotate(0deg) scale(1.05); z-index: 3; box-shadow: 0 40px 100px rgba(118,56,250,0.3); }
    .phone-mockup:nth-child(3) { transform: rotate(5deg) translateY(20px); }
    .phone-screen {
      aspect-ratio: 9/19;
      background: linear-gradient(160deg, #1a1a2e 0%, #16213e 30%, #0f3460 60%, #533483 100%);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: flex-end;
      padding: 24px 16px;
      position: relative;
      overflow: hidden;
    }
    .phone-screen-1 { background: linear-gradient(160deg, #ff6b6b 0%, #ffd93d 50%, #ff6b6b 100%); }
    .phone-screen-2 { background: linear-gradient(160deg, #7638FA 0%, #FF3CA0 50%, #FF7A00 100%); }
    .phone-screen-3 { background: linear-gradient(160deg, #11998e 0%, #38ef7d 100%); }

    .phone-content {
      width: 100%;
      background: rgba(255,255,255,0.15);
      backdrop-filter: blur(8px);
      border-radius: 16px;
      padding: 12px;
    }
    .phone-avatar { width: 28px; height: 28px; border-radius: 50%; background: rgba(255,255,255,0.4); margin-bottom: 8px; }
    .phone-bar { height: 6px; border-radius: 3px; background: rgba(255,255,255,0.5); margin-bottom: 5px; }
    .phone-bar:last-child { width: 60%; }
    .phone-icons { display: flex; justify-content: space-around; margin-top: 16px; }
    .phone-icon { width: 28px; height: 28px; border-radius: 50%; background: rgba(255,255,255,0.25); }

    /* ─── Section Shared ─── */
    .section { padding: 100px 40px; }
    .section-inner { max-width: 1200px; margin: 0 auto; }

    /* ─── Features Section ─── */
    .features { background: var(--gray-100); }
    .features-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 0;
      border-radius: var(--radius-xl);
      overflow: hidden;
      border: 1px solid var(--gray-200);
      box-shadow: var(--shadow-card);
    }
    .features-text {
      padding: 64px 56px;
      background: #fff;
      display: flex;
      flex-direction: column;
      justify-content: center;
    }
    .section-label {
      display: inline-block;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 1.5px;
      text-transform: uppercase;
      color: var(--purple);
      margin-bottom: 20px;
    }
    .section-headline {
      font-size: clamp(26px, 3.5vw, 40px);
      font-weight: 800;
      letter-spacing: -1.2px;
      line-height: 1.15;
      color: var(--black);
      margin-bottom: 24px;
    }
    .section-headline a {
      color: var(--purple);
      text-decoration: none;
      transition: color 0.2s;
    }
    .section-headline a:hover { color: var(--purple-dark); }
    .section-desc {
      font-size: 16px;
      line-height: 1.75;
      color: var(--gray-600);
      margin-bottom: 32px;
      font-weight: 500;
    }
    .section-link {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 15px;
      font-weight: 700;
      color: var(--purple);
      transition: gap 0.2s;
    }
    .section-link:hover { gap: 12px; }
    .section-link svg { width: 18px; height: 18px; stroke: currentColor; stroke-width: 2.5; }

    .features-visual {
      background: linear-gradient(135deg, #f0ebff 0%, #e8f4ff 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 48px;
      min-height: 400px;
    }
    .feature-pills {
      display: flex;
      flex-direction: column;
      gap: 14px;
      width: 100%;
      max-width: 280px;
    }
    .feature-pill {
      display: flex;
      align-items: center;
      gap: 14px;
      padding: 16px 20px;
      border-radius: var(--radius-md);
      background: #fff;
      box-shadow: 0 2px 12px rgba(118,56,250,0.1);
      font-size: 15px;
      font-weight: 600;
      color: var(--black);
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .feature-pill:hover { transform: translateX(4px); box-shadow: 0 4px 20px rgba(118,56,250,0.18); }
    .feature-pill-icon {
      width: 40px; height: 40px;
      border-radius: 12px;
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
      font-size: 20px;
    }

    /* ─── Safety Section ─── */
    .safety { background: #fff; }
    .safety-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 0;
      border-radius: var(--radius-xl);
      overflow: hidden;
      border: 1px solid var(--gray-200);
      box-shadow: var(--shadow-card);
    }
    .safety-visual {
      background: linear-gradient(135deg, #f0fff4 0%, #e8f9ff 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 48px;
      min-height: 400px;
    }
    .safety-cards {
      display: flex;
      flex-direction: column;
      gap: 12px;
      width: 100%;
      max-width: 280px;
    }
    .safety-card {
      padding: 18px 20px;
      border-radius: var(--radius-md);
      background: #fff;
      box-shadow: 0 2px 12px rgba(0,0,0,0.06);
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .safety-card-icon {
      width: 36px; height: 36px;
      border-radius: 10px;
      display: flex; align-items: center; justify-content: center;
      font-size: 18px;
      flex-shrink: 0;
    }
    .safety-card-text { font-size: 14px; font-weight: 600; color: var(--black); }
    .safety-card-sub { font-size: 12px; color: var(--gray-400); font-weight: 500; margin-top: 2px; }

    .safety-text {
      padding: 64px 56px;
      background: #fff;
      display: flex;
      flex-direction: column;
      justify-content: center;
    }
    .safety .section-link { color: #00a86b; }
    .safety .section-label { color: #00a86b; }

    /* ─── Creators Section ─── */
    .creators {
      background: var(--black);
      color: #fff;
      position: relative;
      overflow: hidden;
    }
    .creators-bg {
      position: absolute;
      inset: 0;
      overflow: hidden;
    }
    .creators-blob {
      position: absolute;
      border-radius: 50%;
      filter: blur(100px);
